import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './LandingPage.css';
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';

function LandingPage({ onLogout }) {
  const navigate = useNavigate();
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    document.body.className = darkMode ? 'dark-mode' : 'light-mode';
  }, [darkMode]);

  return (
    <div
      className="landing-wrapper"
      style={{ backgroundImage: `url(${backgroundImage})` }}
    >
      {darkMode && <div className="dark-overlay" />}
      <div className="glass-card">
        <div className="header">
          <h1>Diabetes Prediction System</h1>
          <button className="toggle-btn" onClick={() => setDarkMode(!darkMode)}>
            <img
              src={darkMode ? sunIcon : moonIcon}
              alt="Toggle theme"
              className="theme-icon"
            />
          </button>
        </div>

        <p className="tagline">Empower your health with intelligent insights.</p>

        <div className="button-container">
          <button onClick={() => navigate('/visualization')}>📊 Visualization</button>
          <button onClick={() => navigate('/prediction')}>🧬 Prediction</button>
        </div>

        {/* Bouton Déconnexion */}
        <button
          className="logout-button"
          onClick={() => {
            onLogout();
            navigate('/login');
          }}
        >
          Déconnexion
        </button>
      </div>
    </div>
  );
}

export default LandingPage;
